public String toString() {
    long millis = getMillis();
    StringBuffer buf = new StringBuffer();
    buf.append("PT");
    FormatUtils.appendUnpaddedInteger(buf, millis / 1000);
    long part = Math.abs(millis % 1000);
    if (part > 0) {
        buf.append('.');
        FormatUtils.appendPaddedInteger(buf, part, 3);
    }
    buf.append('S');
    return buf.toString();
}

